"""Aplica, en tu repo real: afuera solo el glosario de sentidos
("¿Qué significa cada sentido?"), y dentro de un solo expander
"Explicación del modelo y palabras influyentes" van juntos el texto de
explicación (LIME + precedentes) y la lista de palabras influyentes.
También el formato estético en los sentidos mostrados (sin guion_bajo,
con Mayúscula inicial).

Uso (desde la RAÍZ del repo, con el venv activado):
    python aplicar_glosario_sentidos.py

Después de correr esto:
    streamlit run demo/streamlit_app.py

    git add -A
    git commit -m "ui: glosario de sentidos afuera, explicacion+palabras juntas adentro"
    git push
"""
import py_compile
import base64
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent

STREAMLIT_APP_B64 = (
    ""
)

DESTINO = "demo/streamlit_app.py"


def main() -> None:
    ruta = REPO_ROOT / DESTINO
    if not ruta.parent.exists():
        print(f"AVISO: no existe la carpeta {ruta.parent} -- revisa que estés en la raíz del repo.")
        return

    contenido = base64.b64decode(STREAMLIT_APP_B64)
    ruta.write_bytes(contenido)
    print(f"Escrito: {DESTINO}")

    py_compile.compile(str(ruta), doraise=True)
    print(f"  compila OK: {DESTINO}")

    print()
    print("Listo. Siguiente paso:")
    print("  streamlit run demo/streamlit_app.py")


if __name__ == "__main__":
    main()
